def get_daily_usage(
    self,
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    username: Optional[str] = None,
    project_name: Optional[str] = None,
    grouping: str = "day",  # NEW PARAMETER
) -> List[Dict[str, Any]]:
    """
    Return per-period aggregated token usage.

    Args:
        grouping: Time grouping level - 'minute', 'hour', or 'day'
    """
    events = self.storage.read_events(
        start_date=start_date,
        end_date=end_date,
        username=username,
        project_name=project_name,
    )
    # Use grouping-specific key function
    key_fn = self._get_grouping_key_fn(grouping)
    aggregated = self._aggregate(events, key_fn)
    return [
        {"period": period, **counts}
        for period, counts in sorted(aggregated.items())
    ]

@staticmethod
def _get_grouping_key_fn(grouping: str):
    """Return key function based on grouping level"""
    if grouping == "minute":
        return lambda e: e.iso_datetime.strftime("%Y-%m-%d %H:%M")
    elif grouping == "hour":
        return lambda e: e.iso_datetime.strftime("%Y-%m-%d %H:00")
    else:  # day
        return lambda e: e.iso_date

