        <h3 class="font-semibold text-sm text-gray-700 mb-3">Metrics</h3>
        <div class="space-y-2">
          <label 
            v-for="metric in availableMetrics" 
            :key="metric.key"
            class="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-2 rounded transition"
          >
            <input 
              v-model="visibleMetrics" 
              :value="metric.key" 
              type="checkbox"
              class="w-4 h-4 rounded cursor-pointer"
            />
            <span 
              class="w-3 h-3 rounded"
              :style="{ backgroundColor: metric.color }"
            ></span>
            <span class="text-sm text-gray-700">{{ metric.label }}</span>
          </label>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import Chart from 'chart.js/auto'

export default {
  name: 'DailyChart',
  props: {
    data: {
      type: Array,
      default: () => []
    },
    grouping: {
      type: String,
      default: 'day',
      validator: (v) => ['minute', 'hour', 'day'].includes(v)
    }
  },
  data() {
    return {
      chart: null,
      visibleMetrics: ['input_tokens', 'output_tokens', 'calls', 'total_cxjcoins'],
      availableMetrics: [
        { key: 'input_tokens', label: 'Input Tokens', color: '#10b981', type: 'line' },
        { key: 'output_tokens', label: 'Output Tokens', color: '#f59e0b', type: 'line' },
        { key: 'calls', label: 'Calls', color: '#3b82f6', type: 'bar' },
        { key: 'total_cxjcoins', label: 'CXJ Coins', color: '#8b5cf6', type: 'bar' }
      ]
    }
  },
  computed: {
    chartConfig() {
      const configs = {
        minute: {
          timeFormat: 'HH:mm',
          tooltipFormat: 'HH:mm',
          displayInterval: 5
        },
        hour: {
          timeFormat: 'HH:00',
          tooltipFormat: 'DD MMM HH:00',
          displayInterval: 2
        },
        day: {
          timeFormat: 'MMM DD',
          tooltipFormat: 'DD MMM YYYY',
          displayInterval: 7
        }
      }
      return configs[this.grouping] || configs.day
    },
    chartData() {
      if (!this.data || this.data.length === 0) {
        return { labels: [], datasets: [] }
      }

      const labels = this.data.map(d => d.period || d.date)
      const datasets = []

      // Build datasets based on visible metrics
      this.availableMetrics.forEach(metric => {
        if (!this.visibleMetrics.includes(metric.key)) return

        const values = this.data.map(d => d[metric.key] || 0)
        const isBar = metric.type === 'bar'

        datasets.push({
          label: metric.label,
          data: values,
          borderColor: metric.color,
          backgroundColor: isBar ? metric.color : `rgba(${this.hexToRgb(metric.color)}, 0.1)`,
          borderWidth: isBar ? 0 : 2,
          tension: isBar ? 0 : 0.4,
          fill: !isBar,
          pointRadius: isBar ? 0 : 3,
          pointBackgroundColor: metric.color,
          type: metric.type,
          yAxisID: this.getYAxisId(metric.key)
        })
      })

      return { labels, datasets }
    }
  },
  watch: {
    chartData: {
      handler() {
        this.updateChart()
      },
      deep: true
    }
  },
  methods: {
    hexToRgb(hex) {
      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
      return result ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}` : '0, 0, 0'
    },
    getYAxisId(metricKey) {
      // Token metrics use left axis, others use right axis
      return ['input_tokens', 'output_tokens'].includes(metricKey) ? 'y' : 'y1'
    },
    updateChart() {
      if (!this.$refs.chartCanvas) return

      if (this.chart) {
        this.chart.data = this.chartData
        this.chart.options = this.getChartOptions()
        this.chart.update()
      } else {
        this.initChart()
      }
    },
    initChart() {
      const ctx = this.$refs.chartCanvas?.getContext('2d')
      if (!ctx) return

      this.chart = new Chart(ctx, {
        type: 'line',
        data: this.chartData,
        options: this.getChartOptions()
      })
    },
    getChartOptions() {
      return {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
          mode: 'index',
          intersect: false
        },
        plugins: {
          legend: {
            display: false
          },
          tooltip: {
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            padding: 12,
            titleFont: { size: 13 },
            bodyFont: { size: 12 },
            mode: 'index',
            intersect: false,
            callbacks: {
              label: (context) => {
                const label = context.dataset.label || ''
                const value = context.parsed.y
                return `${label}: ${value.toFixed(2)}`
              }
            }
          }
        },
        scales: {
          y: {
            type: 'linear',
            display: true,
            position: 'left',
            beginAtZero: true,
            grid: { color: 'rgba(0, 0, 0, 0.05)' },
            ticks: { font: { size: 11 } },
            title: { display: true, text: 'Tokens' }
          },
          y1: {
            type: 'linear',
            display: true,
            position: 'right',
            beginAtZero: true,
            grid: { drawOnChartArea: false },
            ticks: { font: { size: 11 } },
            title: { display: true, text: 'Calls / CXJ Coins' }
          },
          x: {
            grid: { display: false },
            ticks: {
              font: { size: 11 },
              maxRotation: 45,
              minRotation: 0
            }
          }
        }
      }
    }
  },
  mounted() {
    this.initChart()
  },
  beforeUnmount() {
    if (this.chart) {
      this.chart.destroy()
    }
  }
}
</script>
```

